import { proxyActivities, ApplicationFailure } from '@temporalio/workflow';
// It's a convention to import all activities from a single file using a type-only import.
// The Temporal worker will connect the implementation of these activities.
import type * as activities from '../activities/quantum-weaver.activities';

/**
 * @interface AIQuestion
 * @description Defines the structured format for a single question generated by the AI.
 * This type may be shared across the domain in a dedicated types library.
 */
export interface AIQuestion {
  id: string;
  question: string;
  category: 'Market' | 'Finance' | 'Operations';
}

/**
 * @interface QuantumWeaverWorkflowInput
 * @description Defines the input parameters required to start the Quantum Weaver workflow.
 */
export interface QuantumWeaverWorkflowInput {
  userId: string;
  businessPlan: string;
}

/**
 * @interface QuantumWeaverWorkflowResult
 * @description Defines the successful output of the Quantum Weaver workflow.
 */
export interface QuantumWeaverWorkflowResult {
  feedback: string;
  questions: AIQuestion[];
}

// Configure the activities with timeouts and retry policies.
// The `proxyActivities` function creates a client-side stub that communicates with the Temporal service.
const {
  generateBusinessPlanFeedback,
  generateBusinessPlanQuestions,
  notifyAnalysisComplete,
  notifyAnalysisFailed,
} = proxyActivities<typeof activities>({ 
  // Activities that call external services (like a GenAI API) are prone to transient failures.
  startToCloseTimeout: '2 minutes', // Total time allowed for an activity to complete, including all retries.
  retry: {
    initialInterval: '5 seconds', // Wait 5 seconds before the first retry.
    backoffCoefficient: 2, // Double the wait time for each subsequent retry.
    maximumInterval: '30 seconds', // Cap the wait time between retries at 30 seconds.
    // Do not retry on specific application failures that are unlikely to succeed on retry (e.g., invalid input).
    nonRetryableErrorTypes: ['ApplicationFailure'], 
  },
});

/**
 * Defines the Quantum Weaver business plan analysis workflow.
 * 
 * This workflow implements a durable Saga pattern for a complex, long-running business process.
 * It orchestrates a series of activities to analyze a business plan, ensuring that the process
 * either completes successfully or gracefully handles failures with appropriate notifications.
 * 
 * Workflow Saga Steps:
 * 1.  (In Parallel) Generate high-level feedback and critical questions for the business plan.
 * 2.  If successful, notify other services via an event that the analysis is complete.
 * 3.  If any step fails, execute compensation logic: notify other services of the failure.
 * 4.  The workflow's state is persisted by Temporal, making it resilient to process restarts.
 * 
 * @param {QuantumWeaverWorkflowInput} input - The input for the workflow, containing the userId and the business plan text.
 * @returns {Promise<QuantumWeaverWorkflowResult>} A promise that resolves with the analysis results upon successful completion.
 * @throws {ApplicationFailure} The workflow will be marked as 'Failed' in Temporal if any activity fails permanently.
 */
export async function quantumWeaverWorkflow(
  input: QuantumWeaverWorkflowInput,
): Promise<QuantumWeaverWorkflowResult> {
  const { userId, businessPlan } = input;

  try {
    // The two main analysis activities are independent and can run in parallel to improve efficiency.
    const [feedbackResult, questionsResult] = await Promise.all([
      generateBusinessPlanFeedback({ businessPlan }),
      generateBusinessPlanQuestions({ businessPlan }),
    ]);

    const { feedback } = feedbackResult;
    const { questions } = questionsResult;

    // Once the core analysis is complete, trigger a notification activity.
    // This activity is responsible for emitting an event (e.g., to Kafka) to inform other services.
    await notifyAnalysisComplete({ userId, feedback, questions });

    // Return the final result to the workflow caller.
    return { feedback, questions };

  } catch (err) {
    // If any of the main activities fail after all retries, the catch block is executed.
    // This is the compensation part of the Saga.
    const failure = ApplicationFailure.fromError(err);
    const errorMessage = failure.message || 'An unknown error occurred during plan analysis.';
    
    // Trigger a notification activity to inform other services about the failure.
    await notifyAnalysisFailed({ userId, businessPlan, error: errorMessage });

    // Re-throwing the error is crucial. It ensures the workflow execution is marked as 'Failed'
    // in Temporal's visibility records, which is important for monitoring and auditing.
    throw failure;
  }
}
